def encode(lat, lon, prec=8):
    a, o = [-90.0, 90.0], [-180.0, 180.0]
    bits = ch = 0
    even = True
    out = []
    while len(out) < prec:
        if even:
            m = sum(o) / 2
            ch = (ch << 1) | 1 if lon >= m else ch << 1
            o[0 if lon >= m else 1] = m
